head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil16500";
scwin.clear = null;

///////// 2. 초기화 영역 /////////
// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — ldMktTpCd

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_ldMktTpCd", fn: function(){ return ((dma_pageContext.get("ldMktTpCd") ?? "") === '1'); } }, { id: "if_ldMktTpCd_2", fn: function(){ return ((dma_pageContext.get("ldMktTpCd") ?? "") === '2'); } }, { id: "if_ldMktTpCd_3", fn: function(){ return ((dma_pageContext.get("ldMktTpCd") ?? "") === '6'); } }, { id: "if_ldMktTpCd_4", fn: function(){ return ((dma_pageContext.get("ldMktTpCd") ?? "") === '1' || (dma_pageContext.get("ldMktTpCd") ?? "") === '2'); } }, { id: "if_ldMktTpCd_5", fn: function(){ return ((dma_pageContext.get("ldMktTpCd") ?? "") === '6'); } }, { id: "if_ldMktTpCd_6", fn: function(){ return ((dma_pageContext.get("ldMktTpCd") ?? "") === '1' || (dma_pageContext.get("ldMktTpCd") ?? "") === '2'); } }, { id: "if_ldMktTpCd_7", fn: function(){ return ((dma_pageContext.get("ldMktTpCd") ?? "") === '6'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

// [A] 초기 목록 미해결 — 자기 목록을 채우는 tx 가 3개다(tx_fn_Search, tx_fn_Register, tx_fn_Remove) — 어느 것이 «열자마자» 인지 정할 근거가 없다

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.clear = clear;
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil16500.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name cal_disclsEduStrtDd_onblur
 * @description cal_disclsEduStrtDd 포커스 이탈 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cal_disclsEduStrtDd_onblur = async function(e){
    try {
        await (async (c) => { const raw = String((c && c.getValue) ? (c.getValue() ?? "") : ""); if (raw.length === 0) { return true; } const v = raw.split("-").join("").split("/").join(""); if (c && c.setValue) { c.setValue(v); } const lbl = ""; const lp = lbl ? (lbl + ": ") : ""; if (v.length !== 8) { await $c.win.alert(lp + "날짜는 8 자리 YYYYMMDD 형식입니다."); if (c && c.focus) { c.focus(); } return false; } let digits = true; for (let i = 0; i < v.length; i++) { const ch = v.charAt(i); if (ch < "0" || ch > "9") { digits = false; break; } } if (!digits) { await $c.win.alert(lp + "숫자만 입력가능합니다."); if (c && c.focus) { c.focus(); } return false; } const mm = Number(v.substring(4, 6)); if (mm > 12 || mm < 1) { await $c.win.alert(lp + "달은 1 에서 12 사이여야 합니다."); if (c && c.focus) { c.focus(); } return false; } if (!$c.date.checkCalendarFormat(c, "yyyyMMdd", { clearOnInvalid: false })) { await $c.win.alert(lp + " 존재하지 않는 날짜입니다."); if (c && c.focus) { c.focus(); } return false; } return true; })($c.util.getComponent("cal_disclsEduStrtDd"));

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil16500.cal_disclsEduStrtDd_onblur' }); }
};

