/**
 * @method
 * @name trans_img_onclick
 * @description trans_img 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trans_img_onclick = async function(e){
    try {
        await scwin.register()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil16500.trans_img_onclick' }); }
};

/**
 * @method
 * @name grd_EduScheduleList_oncellclick
 * @description grd_EduScheduleList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_EduScheduleList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_EduScheduleList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_EduScheduleList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        scwin.modify(r["disclsEduApplSeq"], r["disclsEduApctTpCd"], r["disclsEduCrsNm"], r["disclsEduStrtDd"], r["disclsEduEndDd"], r["disclsEduAcptStrtDd"], r["disclsEduAcptEndDd"], r["disclsEduEvtItmExpYn"], r["partcPersInputYn"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_EduScheduleList.oncellclick' });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Search
 * @description Search 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Search = async function () {
    // ⛔주소를 정할 수 없다 — as-is 문서 위치를 못 찾았다(⛔못 쟀다 — as-is JSP 위치 미상).
    //   추정 주소로 내보내면 «엉뚱한 곳으로 조용히» 나간다. 불릴 때 드러나게 실패시킨다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "제출 주소를 찾지 못했습니다(전환 미완) — eduManagement.do"
    throw { bizMessage: "제출 주소를 찾지 못했습니다(전환 미완) — eduManagement.do", unresolved: "action:eduManagement.do" };
};

