///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function () {
    const frm = (document.eduManagementForm || { elements: [] });
    $c.util.getComponent('dma_SearchReq').set('method', 'searchRgtEduSchedule');
    frm.action = 'eduManagement.do';
    $c.util.getComponent('dma_SearchReq').set('SCREN_PROCES_TP_CD', "01");
    await scwin.tx_fn_Search();
};

/**
 * @method
 * @name check_in
 * @description check in 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.check_in = async function () {
    const form = $c.util.getComponent('eduManagementForm');
    if ($c.util.getComponent('slc_disclsEduApctTpCd').getValue() === "" || $c.util.getComponent('slc_disclsEduApctTpCd').getValue().indexOf(" ") === "") {
        await $c.win.alert("공시교육대상자를 선택해 주세요");
        $c.util.getComponent("slc_disclsEduApctTpCd").focus();
        return;
    }
    if (($c.util.getComponent('ipt_disclsEduCrsNm').getValue() == null ? '' : String($c.util.getComponent('ipt_disclsEduCrsNm').getValue())) === '' || $c.util.getComponent('ipt_disclsEduCrsNm').getValue().indexOf(" ") === "") {
        await $c.win.alert("공시교육회차를 입력해 주세요");
        $c.util.getComponent("ipt_disclsEduCrsNm").focus();
        return;
    }
    if (($c.util.getComponent('cal_disclsEduStrtDd').getValue() == null ? '' : String($c.util.getComponent('cal_disclsEduStrtDd').getValue())) === '' || $c.util.getComponent('cal_disclsEduStrtDd').getValue().indexOf(" ") === "") {
        await $c.win.alert("공시교육일정 시작일을 입력해 주세요");
        $c.util.getComponent("cal_disclsEduStrtDd").focus();
        return;
    }
    if (($c.util.getComponent('cal_disclsEduEndDd').getValue() == null ? '' : String($c.util.getComponent('cal_disclsEduEndDd').getValue())) === '' || $c.util.getComponent('cal_disclsEduEndDd').getValue().indexOf(" ") === "") {
        await $c.win.alert("공시교육일정 종료일을 입력해 주세요");
        $c.util.getComponent("cal_disclsEduEndDd").focus();
        return;
    }
    if ($c.util.getComponent('cal_disclsEduStrtDd').getValue()> $c.util.getComponent('cal_disclsEduEndDd').getValue()) {
        await $c.win.alert("공시교육일정 시작일자는 종료일자 보다 작거나 같아야 합니다");
        $c.util.getComponent("cal_disclsEduStrtDd").focus();
        return;
    }
    if (($c.util.getComponent('cal_disclsEduAcptStrtDd').getValue() == null ? '' : String($c.util.getComponent('cal_disclsEduAcptStrtDd').getValue())) === '' || $c.util.getComponent('cal_disclsEduAcptStrtDd').getValue().indexOf(" ") === "") {
        await $c.win.alert("공시교육 접수일정 시작일을 입력해 주세요");
        $c.util.getComponent("cal_disclsEduAcptStrtDd").focus();
        return;
    }
    if (($c.util.getComponent('cal_disclsEduAcptEndDd').getValue() == null ? '' : String($c.util.getComponent('cal_disclsEduAcptEndDd').getValue())) === '' || $c.util.getComponent('cal_disclsEduAcptEndDd').getValue().indexOf(" ") === "") {
        await $c.win.alert("공시교육 접수일정 종료일을 입력해 주세요");
        $c.util.getComponent("cal_disclsEduAcptEndDd").focus();
        return;
    }
    if ($c.util.getComponent('cal_disclsEduAcptStrtDd').getValue()> $c.util.getComponent('cal_disclsEduAcptEndDd').getValue()) {
        await $c.win.alert("공시교육 접수일정 시작일자는 종료일자 보다 작거나 같아야 합니다");
        $c.util.getComponent("cal_disclsEduAcptStrtDd").focus();
        return;
    }
    if (($c.util.getComponent('slc_disclsEduEvtItmExpYn').getValue() == null ? '' : String($c.util.getComponent('slc_disclsEduEvtItmExpYn').getValue())) === '' || $c.util.getComponent('slc_disclsEduEvtItmExpYn').getValue().indexOf(" ") === "") {
        await $c.win.alert("간담회 항목 사용여부를 선택해 주세요");
        $c.util.getComponent("slc_disclsEduEvtItmExpYn").focus();
        return;
    }
    if (($c.util.getComponent('slc_partcPersInputYn').getValue() == null ? '' : String($c.util.getComponent('slc_partcPersInputYn').getValue())) === '' || $c.util.getComponent('slc_partcPersInputYn').getValue().indexOf(" ") === "") {
        await $c.win.alert("참가인원 입력여부를 선택해 주세요");
        $c.util.getComponent("slc_partcPersInputYn").focus();
        return;
    }
    return true;
};

/**
 * @method
 * @name register
 * @description register 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.register = async function () {
    if (await scwin.check_in()) {
        if ($c.util.getComponent('dma_SearchReq').get('task') === "register") {
            $c.util.getComponent('dma_SearchReq').set('method', 'registerEduSchedule');
            $c.util.getComponent('dma_SearchReq').set('SCREN_PROCES_TP_CD', "02");
        } else {
            $c.util.getComponent('dma_SearchReq').set('method', 'modifyEduSchedule');
            $c.util.getComponent('dma_SearchReq').set('SCREN_PROCES_TP_CD', "03");
        }
        (document.eduManagementForm || { elements: [] }).action = 'eduManagement.do';
        await scwin.tx_fn_Register();
    }
};

/**
 * @method
 * @name modify
 * @description modify 처리
 * @param {*} Seq Seq
 * @param {String} Cd Cd
 * @param {String} CrsNm CrsNm
 * @param {String} EduStrtDd EduStrtDd
 * @param {String} EduEndDd EduEndDd
 * @param {String} EduAcptStrtDd EduAcptStrtDd
 * @param {String} EduAcptEndDd EduAcptEndDd
 * @param {String} disclsEduEvtItmExpYn disclsEduEvtItmExpYn
 * @param {String} partcPersInputYn partcPersInputYn
 * @returns {void}
 * @hidden N
 */
scwin.modify = function (Seq, Cd, CrsNm, EduStrtDd, EduEndDd, EduAcptStrtDd, EduAcptEndDd, disclsEduEvtItmExpYn, partcPersInputYn) {
    const form = (document.eduManagementForm || { elements: [] });
    $c.util.getComponent('dma_SearchReq').set('disclsEduApplSeq', Seq);
    scwin.selectedBox($c.util.getComponent('slc_disclsEduApctTpCd'), Cd);
    $c.util.getComponent("ipt_disclsEduCrsNm").setValue(CrsNm);
    $c.util.getComponent("cal_disclsEduStrtDd").setValue(EduStrtDd);
    $c.util.getComponent("cal_disclsEduEndDd").setValue(EduEndDd);
    $c.util.getComponent("cal_disclsEduAcptStrtDd").setValue(EduAcptStrtDd);
    $c.util.getComponent("cal_disclsEduAcptEndDd").setValue(EduAcptEndDd);
    if (disclsEduEvtItmExpYn === '사용') {
        $c.util.getComponent("slc_disclsEduEvtItmExpYn").setValue('Y');
    } else {
        if (disclsEduEvtItmExpYn === '미사용') {
            $c.util.getComponent("slc_disclsEduEvtItmExpYn").setValue('N');
        } else {
            $c.util.getComponent("slc_disclsEduEvtItmExpYn").setValue('');
        }
    }
    if (partcPersInputYn === '입력') {
        $c.util.getComponent("slc_partcPersInputYn").setValue('Y');
    } else {
        if (partcPersInputYn === '미입력') {
            $c.util.getComponent("slc_partcPersInputYn").setValue('N');
        } else {
            $c.util.getComponent("slc_partcPersInputYn").setValue('');
        }
    }
    $c.util.getComponent('dma_SearchReq').set('task', "modify");
    ($c.util.getComponent("txt_newInsert") && $c.util.getComponent("txt_newInsert").setValue) ? $c.util.getComponent("txt_newInsert").setValue("<img src='/img/btn/btn_regist_2.gif'  onclick='clear()' style='cursor:hand;'>") : (($c.util.getComponent("txt_newInsert") && $c.util.getComponent("txt_newInsert").setText) ? $c.util.getComponent("txt_newInsert").setText("<img src='/img/btn/btn_regist_2.gif'  onclick='clear()' style='cursor:hand;'>") : (console.warn('[sdd] 값 쓰기 미지원 컴포넌트: ' + "txt_newInsert"), void ("<img src='/img/btn/btn_regist_2.gif'  onclick='clear()' style='cursor:hand;'>")));
    $c.util.getComponent("trans_img").src = "/img/btn/btn_edit.gif";
};

function clear() {
    const form = (document.eduManagementForm || { elements: [] });
    $c.util.getComponent('dma_SearchReq').set('disclsEduApplSeq', "");
    scwin.selectedBox($c.util.getComponent('slc_disclsEduApctTpCd'), "");
    $c.util.getComponent("ipt_disclsEduCrsNm").setValue("");
    $c.util.getComponent("cal_disclsEduStrtDd").setValue("");
    $c.util.getComponent("cal_disclsEduEndDd").setValue("");
    $c.util.getComponent("cal_disclsEduAcptStrtDd").setValue("");
    $c.util.getComponent("cal_disclsEduAcptEndDd").setValue("");
    $c.util.getComponent("slc_disclsEduEvtItmExpYn").setValue("");
    $c.util.getComponent("slc_partcPersInputYn").setValue("");
    $c.util.getComponent('dma_SearchReq').set('task', "register");
    ($c.util.getComponent("txt_newInsert") && $c.util.getComponent("txt_newInsert").setValue) ? $c.util.getComponent("txt_newInsert").setValue("") : (($c.util.getComponent("txt_newInsert") && $c.util.getComponent("txt_newInsert").setText) ? $c.util.getComponent("txt_newInsert").setText("") : (console.warn('[sdd] 값 쓰기 미지원 컴포넌트: ' + "txt_newInsert"), void ("")));
    $c.util.getComponent("trans_img").src = "/img/btn/btn_regist_2.gif";
}

/**
 * @method
 * @name remove
 * @description remove 처리
 * @param {*} Seq Seq
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.remove = async function (Seq) {
    const form = (document.eduManagementForm || { elements: [] });
    const rtn = await $c.win.confirm('삭제 하시겠습니까?');
    if (rtn === 1) {
        $c.util.getComponent('dma_SearchReq').set('disclsEduApplSeq', Seq);
        $c.util.getComponent('dma_SearchReq').set('method', 'removeEduSchedule');
        form.action = 'eduManagement.do';
        $c.util.getComponent('dma_SearchReq').set('SCREN_PROCES_TP_CD', "04");
        await scwin.tx_fn_Remove();
    }
};

/**
 * @method
 * @name selectedBox
 * @description selected Box 처리
 * @param {Object} obj 컴포넌트
 * @param {*} val val
 * @returns {void}
 * @hidden N
 */
scwin.selectedBox = function (obj, val) {
    let selectedIndexNum = 0;
    for (i = 0; i < obj.length; i++) {
        if (obj.options[i].value === val) {
            selectedIndexNum = i;
        }
    }
    obj.selectedIndex = selectedIndexNum;
};

/**
 * @method
 * @name krxpage_pagenavigator_150_onclick
 * @description krxpage_pagenavigator_150 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_150_onclick = async function (index) { const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; try { $c.util.getComponent('dma_SearchReq').set('pageIndex', pi); } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'krxpage_pagenavigator_150.page' }); } await scwin.search(); };
